<?php
declare(strict_types=1);
require_once __DIR__ . '/api/site_lib.php';
$target = 'assets/targets/picture.jpg?v=' . asset_version('assets/targets/picture.jpg');
$exists = is_file(project_root() . '/assets/targets/picture.jpg');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Compile Target | AR Game Shooter</title><link rel="stylesheet" href="assets/css/game.css"><script src="https://cdn.jsdelivr.net/npm/mind-ar@1.2.5/dist/mindar-image.prod.js"></script></head><body class="site-shell"><main class="narrow-page"><a class="eyebrow" href="index.php">← AR GAME SHOOTER</a><h1>Compile image target</h1><p class="lede">Turn the current target image into tracking data directly in the browser.</p><div class="compile-panel"><div class="target-frame"><?php if ($exists): ?><img src="<?= h($target) ?>" alt="Current AR target" id="targetPreview"><?php else: ?><div class="empty-state">Upload a target image first.</div><?php endif; ?></div><div id="compileStatus" class="status">Ready</div><button class="button button-primary" id="compileButton" <?= $exists ? '' : 'disabled' ?>>Compile target</button></div></main><script type="module">const button=document.querySelector('#compileButton');const status=document.querySelector('#compileStatus');button?.addEventListener('click',async()=>{button.disabled=true;try{status.textContent='Loading target image...';const image=document.querySelector('#targetPreview');const compiler=new MINDAR.IMAGE.Compiler();await new Promise((resolve,reject)=>{image.complete?resolve():image.addEventListener('load',resolve,{once:true});image.addEventListener('error',reject,{once:true})});status.textContent='Compiling...';const data=await compiler.compileImageTargets([image],p=>status.textContent='Compiling... '+Math.round(p*100)+'%');status.textContent='Saving...';const buffer=await compiler.exportData(data);const response=await fetch('save-target.php',{method:'POST',body:buffer});if(!response.ok)throw new Error('save failed');status.textContent='Done. Target is ready.';setTimeout(()=>location.href='index.php?saved=1',900)}catch(error){console.error(error);status.textContent='Target compilation failed. Check the image and try again.';button.disabled=false}});</script></body></html>
